S.append(TB(c,B+' · 2','Bảng tổng hợp bộ chọn',['Bộ chọn','Ý nghĩa','Trên trang mẫu'],[['<code>p</code>','mọi p','%d'%N['p']],['<code>.note</code>','mọi phần tử có class note','%d'%N['.note']],['<code>#menu</code>','phần tử id=menu','%d'%N['#menu']],['<code>div p</code>','p ở mọi cấp trong div','%d'%N['div p']],['<code>div &gt; p</code>','p là con trực tiếp của div','%d'%N['div > p']],['<code>h2 + p</code>','p ngay sau h2','%d'%N['h2 + p']],['<code>h2 ~ p</code>','mọi p sau h2 cùng cha','%d'%N['h2 ~ p']],['<code>p, h2</code>','nhóm p và h2','%d'%N['p, h2']],['<code>a[href]</code>','a có thuộc tính href','%d'%N['a[href]']]],note=KEY('Các số đếm trên được <b>chạy thật</b> trên trang mẫu bằng trình duyệt.')))
