S.append(S2(c,B+' · 3','Lớp giả (pseudo-class)',card('Trạng thái của phần tử, viết sau MỘT dấu :',P('<b>a:link</b> chưa thăm; <b>a:visited</b> <b>đã thăm</b>; <b>a:hover</b> <b>khi trỏ chuột lên</b>; <b>a:active</b> khi đang nhấn.','<b>:focus</b> ô đang nhập.','<b>:first-child, :nth-child(n)</b>: theo vị trí.','Thứ tự nên viết: <b>link → visited → hover → active</b>.')),CODE('a:hover   { color: red; }\na:visited { color: purple; }\nli:first-child { font-weight: bold; }',20)+BROWSER('<a href="#">Trỏ chuột vào đây</a><ul><li>Mục đầu</li><li>Mục hai</li></ul>','a:hover{color:red;font-weight:bold}li:first-child{background:#FFF59D}',h=140)+KEY('Hover: <b>a:hover</b>; đã thăm: <b>a:visited</b>. Lớp giả dùng <b>1 dấu hai chấm</b>.')))
S.append(S2(c,B+' · 3','Phần tử giả (pseudo-element)',card('Một phần nội dung, viết sau HAI dấu ::',P('<b>::first-line</b>: <b>dòng đầu</b> của đoạn.','<b>::first-letter</b>: <b>kí tự đầu</b>.','<b>::before / ::after</b>: chèn nội dung bằng thuộc tính <b>content</b>.','<b>::selection</b>: phần chữ đang bôi chọn.')),CODE('p::first-line   { color: red; }\np::first-letter { font-size: 2em; }\nh2::before { content: "★ "; }',20)+BROWSER('<h2>Tin nổi bật</h2><p>HTML là ngôn ngữ đánh dấu siêu văn bản dùng để tạo trang web và CSS định dạng nó rất linh hoạt cho mọi thiết bị.</p>','p::first-line{color:#C62828}p::first-letter{font-size:2em;font-weight:bold}h2::before{content:"★ "}',h=190)+KEY('<b>::first-line</b> chỉ tô <b>dòng đầu tiên</b> của đoạn.')))
S.append(TB(c,B+' · 3','Phân biệt lớp giả và phần tử giả',['','Lớp giả','Phần tử giả'],[['Dấu','<b>một</b> dấu :','<b>hai</b> dấu ::'],['Ý nghĩa','<b>trạng thái / vị trí</b> của phần tử','<b>một phần</b> của phần tử'],['Ví dụ','a:hover, li:first-child','p::first-line, ::before'],['Trọng số','<b>10</b> (như class)','<b>1</b> (như thẻ)']],note=KEY('Trọng số SGK: lớp giả = <b>10</b>; phần tử giả = <b>1</b>. Sẽ dùng ở bài mức ưu tiên.')))
